  .plot("test-theme.R: adding theme object to ggplot object with + operator works #2", p <- p + theme(axis.title = element_text(size = 20)))
  .plot("test-theme.R: adding theme object to ggplot object with + operator works #3", p <- p + theme(text = element_text(colour = 'red')))
