  tt@colour <- 'red'
  tt@inherit.blank <- FALSE
  .plot("test-theme.R: adding theme object to ggplot object with + operator works #4", p <- ggplot(data.frame(x = 1:3), aes(x, x)) + geom_point())
  .plot("test-theme.R: adding theme object to ggplot object with + operator works #5", p <- p + theme(axis.title = element_text(size = 20)))
