  .plot("test-theme.R: adding theme object to ggplot object with + operator works #7", p <- ggplot(data.frame(x = 1:3), aes(x, x)) + geom_point())
  .plot("test-theme.R: adding theme object to ggplot object with + operator works #8", p1 <- p + theme_light() +
      theme(axis.line.x = element_line(color = "blue")) +
      theme(axis.ticks.x = element_line(color = "red")))
  .plot("test-theme.R: adding theme object to ggplot object with + operator works #9", p2 <- p + theme_light() +
