corpus_block("test-theme.R: complete and non-complete themes interact correctly with ggplot objects", {
  skip_on_cran()
  .plot("test-theme.R: complete and non-complete themes interact correctly with ggplot objects #1", base <- ggplot(data.frame(x = 1:3), aes(x, x)) + geom_point())
  .plot("test-theme.R: complete and non-complete themes interact correctly with ggplot objects #2", base + theme_bw() + theme(text = element_text(colour = "red")))
  p <- ggplot_build(base + theme_bw() + theme(text = element_text(colour = 'red')))
  pt <- p@plot@theme
  tt <- theme_bw() + theme(text = element_text(colour = 'red'))
  pt <- pt[order(names(pt))]
  tt <- tt[order(names(tt))]
  .plot("test-theme.R: complete and non-complete themes interact correctly with ggplot objects #3", base + theme(text = element_text(colour = "red")) + theme_bw())
