  pt <- p@plot@theme
  tt <- theme(text = element_text(colour = 'red')) + theme_bw()
  pt <- pt[order(names(pt))]
  tt <- tt[order(names(tt))]
  .plot("test-theme.R: complete and non-complete themes interact correctly with ggplot objects #4", base + theme(text = element_text(colour = "red", face = "italic")))
  p <- ggplot_build(base + theme(text = element_text(colour = 'red', face = 'italic')))
  .plot("test-theme.R: complete and non-complete themes interact correctly with ggplot objects #5", base + theme(text = element_text(colour = "red")) + theme(text = element_text(face = "italic")))
